def _community_timeout_bucket(raw_timeout: Any) -> str:
    """Bucket the configured tool timeout for anonymous telemetry."""
    try:
        timeout_value = int(raw_timeout or 0)
    except (TypeError, ValueError):
        timeout_value = 0
    if timeout_value <= 0:
        return ""
    if timeout_value <= 30:
        return "0-30"
    if timeout_value <= 60:
        return "31-60"
    if timeout_value <= 120:
        return "61-120"
    return "120+"

