async def dispatch_chat_message(
    request: Request,
    user: AdminUser,
    message: str,
    *,
    source: str,
    success_flash: str,
    note: str = "",
) -> Response:
    """Send one main-chat message and persist dashboard and usage state."""
    config = config_service.load()
    community_hints = await build_chat_community_hints(config)
    outbound_message = message
    community_context = build_chat_community_context_text(community_hints)
    if community_context:
        outbound_message = f"{community_context}\n\nUser request:\n{message}"
    try:
        result = await agent_service.send_message(user, outbound_message)
        clear_error()
        config_service.set_last_successful_chat(
            {
                "at": _utc_now(),
                "user_message": message[:240],
                "assistant_preview": str(result["content"])[:240],
                "community_context_count": len(community_hints),
            }
        )
        record_usage(
            source=source,
            provider=str(result.get("provider", "")),
            model=str(result.get("model", "")),
            usage=result.get("usage"),
            note=note,
        )
    except ValueError as exc:
        gui_logger.exception("chat_send_failed user=%s", user.username)
        friendly = store_error(str(exc), context="provider")
        _set_flash(request, friendly["title"] + ": " + friendly["next_action"], level="error")
        if _is_htmx_request(request):
            return await render_chat_page(request, user, draft=message, partial=True)
        return RedirectResponse("/chat", status_code=303)
    except Exception as exc:
        gui_logger.exception("chat_send_failed user=%s", user.username)
        friendly = store_error(str(exc), context="general")
        _set_flash(request, friendly["title"] + ": " + friendly["next_action"], level="error")
        if _is_htmx_request(request):
            return await render_chat_page(request, user, draft=message, partial=True)
        return RedirectResponse("/chat", status_code=303)

    _set_flash(request, success_flash)
    if _is_htmx_request(request):
        return await render_chat_page(request, user, partial=True)
    return RedirectResponse("/chat", status_code=303)

