    if (
        upload is not None
        and hasattr(upload, "filename")
        and hasattr(upload, "file")
        and str(getattr(upload, "filename", "")).strip()
    ):
        try:
            uploaded = _store_chat_upload(upload, config_service.uploads_dir, config_service.default_workspace)
