            entries = [entry for entry in entries if needle in str(entry.get("line", "")).lower()]
    else:
        entries = [{"level": "info", "label": "INFO", "line": "No GUI logs have been written yet."}]

    return _render(
        request,
        "logs.html",
        {
            "title": "Logs",
            "nav_active": "logs",
            "user": user,
            "log_file": str(log_file),
